{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SUNBEAM_DB.MAPLEMONK.SUNBEAM_SKU_MASTER AS WITH SKU_MASTER AS ( SELECT CASE WHEN COALESCE(IM.MRP, PL.MRP) = \'\' THEN NULL ELSE COALESCE(IM.MRP, PL.MRP) END AS MRP, PL.\"SKU Code\" AS SKU_CODE, PL.CHANNELNAME, CASE WHEN UPPER(PL.CHANNELNAME) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%SNAPDEAL%\' THEN \'SNAPDEAL\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%PHARMEASY%\' THEN \'PHARMEASY\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%MEESHO%\' THEN \'MEESHO\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%SHOPCLUES%\' THEN \'SHOPCLUES\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%FIRSTCRY%\' THEN \'FIRSTCRY\' WHEN UPPER(PL.CHANNELNAME) LIKE \'%ONDCCOSTBO%\' THEN \'ONDC\' ELSE PL.CHANNELNAME END AS FINAL_MARKETPLACE, PL.\"Seller SKU on Channel\" AS CHANNEL_SKU, PL.\"Selling Price\" AS SELLING_PRICE, PL.\"Channel Product Id\" AS PRODUCT_ID, COALESCE( PL.\"Product Name on Channel\", IM.NAME ) AS PRODUCT_NAME, COALESCE( IM.IMAGE_URL, IMAGE.URL, NULLIF(TRIM(PL.URL), \'\') ) AS URL, IM.SIZE, CASE WHEN IM.COST_PRICE = \'\' THEN NULL ELSE TRY_TO_DOUBLE(IM.COST_PRICE) END AS COST, IM.CATEGORY_CODE AS CATEGORY_CODE, IM.CATEGORY_NAME AS CATEGORY, CASE WHEN UPPER(IM.BRAND) LIKE \'%IN YOU%\' OR UPPER(IM.BRAND) LIKE \'%INYOU%\' THEN \'IN YOU\' ELSE UPPER(IM.BRAND) END AS BRAND, ROW_NUMBER() OVER ( PARTITION BY COALESCE( PL.\"SKU Code\", IM.SKU_CODE, PL.\"Seller SKU on Channel\" ), PL.CHANNELNAME, PL.\"Channel Product Id\" ORDER BY COALESCE(IM.MRP, PL.MRP) DESC ) AS RN FROM SUNBEAM_DB.MAPLEMONK.SUNBEAM_UNICOMMERCE_GET_PRODUCT_LISTING PL LEFT JOIN ( SELECT \"Product Code\" AS SKU_CODE, MRP, NAME, SIZE, \"Cost Price\" as COST_PRICE, \"Category Code\" as CATEGORY_CODE, \"Category Name\" as CATEGORY_NAME, UPPER(BRAND) AS BRAND, NULLIF(TRIM(\"Image Url\"), \'\') AS IMAGE_URL FROM SUNBEAM_DB.MAPLEMONK.SUNBEAM_UNICOMMERCE_GET_PRODUCT_MASTER QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(\"Product Code\") ORDER BY 1 DESC ) = 1 ) IM ON LOWER(TRIM(PL.\"SKU Code\")) = LOWER(TRIM(IM.SKU_CODE)) LEFT JOIN ( SELECT UPPER(\"SKU Code\") AS SKU, NULLIF(TRIM(URL), \'\') AS URL FROM SUNBEAM_DB.MAPLEMONK.SUNBEAM_UNICOMMERCE_GET_PRODUCT_LISTING QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(\"SKU Code\") ORDER BY NULLIF(TRIM(URL), \'\') DESC ) = 1 ) IMAGE ON LOWER(IMAGE.SKU) = LOWER(TRIM(PL.\"SKU Code\")) WHERE PL.\"Status Code\" = \'LINKED\' ) SELECT * FROM SKU_MASTER WHERE RN = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SUNBEAM_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            